import {escapeHtml as e} from './package-core.js';
const transportFields=['base_url','vision','json_mode','token_parameter','thinking_mode','max_output_tokens'];
export class ProviderEditor {
  constructor(container,{api,server,primary}){this.container=container;this.api=api;this.server=server;this.primary=primary;this.keys=new Map();this.values=[];
    container.addEventListener('input',event=>{if(event.target.dataset.providerField!=='base_url')return;const card=event.target.closest('.provider-card'),id=card.dataset.providerId,row=this.values.find(v=>v.ui_id===id),url=event.target.value.trim().replace(/\/+$/,'');if(row&&url!==row.base_url.replace(/\/+$/,'')){card.querySelector('[data-provider-field="api_key"]').value='';this.keys.delete(id);if(url!==this.primary().base_url.replace(/\/+$/,''))card.querySelector('[data-provider-field="inherit_primary_key"]').checked=false;row.base_url=event.target.value.trim();}});
    container.addEventListener('click',event=>{const button=event.target.closest('[data-provider-action]');if(button)this.action(button).catch(error=>{button.closest('.provider-card').querySelector('[data-provider-status]').textContent=error.message;});});}
  open(values=[]){this.values=values.map((v,i)=>({...v,ui_id:v.ui_id||crypto.randomUUID()}));this.render();}
  add(){this.capture();const p=this.primary();this.values.push({ui_id:crypto.randomUUID(),name:'备用服务 '+(this.values.length+1),...Object.fromEntries(transportFields.map(k=>[k,p[k]])),models:[...new Set([p.translation_model,p.layout_model].filter(Boolean))],inherit_primary_key:true});this.render();}
  render(){this.container.innerHTML=this.values.map((v,i)=>`<div class="provider-card" data-provider-id="${e(v.ui_id)}"><div class="provider-heading"><strong>回退 ${i+1}</strong><div><button type="button" data-provider-action="up" ${i===0?'disabled':''}>上移</button><button type="button" data-provider-action="down" ${i===this.values.length-1?'disabled':''}>下移</button><button type="button" data-provider-action="remove">移除</button></div></div><div class="form-grid"><label>服务名称<input data-provider-field="name" value="${e(v.name)}" maxlength="80" required></label><label>Base URL<input data-provider-field="base_url" type="url" value="${e(v.base_url)}" required></label><label class="full-span">API Key<input data-provider-field="api_key" type="password" value="${e(this.keys.get(v.ui_id)||'')}" autocomplete="off"></label><label class="checkbox full-span"><input data-provider-field="inherit_primary_key" type="checkbox" ${v.inherit_primary_key?'checked':''}> 相同 Base URL 时复用主服务密钥</label><label class="full-span">模型顺序（每行一个，最多 4 个）<textarea data-provider-field="models" rows="2" required>${e((v.models||[]).join('\n'))}</textarea></label><label>输出 token 上限<input data-provider-field="max_output_tokens" type="number" min="1024" max="32768" value="${v.max_output_tokens||8192}"></label><label>Token 参数<select data-provider-field="token_parameter"><option value="max_tokens" ${v.token_parameter==='max_tokens'?'selected':''}>max_tokens</option><option value="max_completion_tokens" ${v.token_parameter==='max_completion_tokens'?'selected':''}>max_completion_tokens</option></select></label><label>思考模式<select data-provider-field="thinking_mode">${[['auto','服务默认'],['disabled','关闭思考'],['enabled','启用思考']].map(([key,label])=>`<option value="${key}" ${v.thinking_mode===key?'selected':''}>${label}</option>`).join('')}</select></label><label class="checkbox"><input data-provider-field="vision" type="checkbox" ${v.vision?'checked':''}> 支持图像</label><label class="checkbox"><input data-provider-field="json_mode" type="checkbox" ${v.json_mode?'checked':''}> JSON 模式</label></div><div class="provider-actions"><button type="button" data-provider-action="detect" ${!this.server()?'disabled':''}>自动检测模型</button><button type="button" data-provider-action="test" ${!this.server()?'disabled':''}>测试模型</button><span data-provider-status role="status"></span></div><div data-provider-models class="model-list"></div></div>`).join('');}
  capture(){this.values=[...this.container.querySelectorAll('.provider-card')].map(card=>{const result={ui_id:card.dataset.providerId};for(const input of card.querySelectorAll('[data-provider-field]')){const key=input.dataset.providerField;let value=input.type==='checkbox'?input.checked:input.value.trim();if(key==='api_key'){this.keys.set(result.ui_id,value);continue;}if(key==='models')value=[...new Set(value.split(/\n|,/).map(x=>x.trim()).filter(Boolean))];if(key==='max_output_tokens')value=Number(value);result[key]=value;}return result;});return this.values;}
  runtime(values=this.capture(),allowEmpty=false){const primary=this.primary();return values.map(({ui_id,...v})=>{if(v.inherit_primary_key&&v.base_url.replace(/\/+$/,'')!==primary.base_url.replace(/\/+$/,''))throw Error('备用服务更换地址时，请取消复用主密钥并填写该服务自己的密钥');if((!allowEmpty&&!v.models.length)||v.models.length>4)throw Error('每个备用服务请填写 1–4 个模型');return {...v,api_key:this.keys.get(ui_id)||''};});}
  safe(){this.capture();this.runtime();return this.values.map(v=>({...v}));}
  async action(button){this.capture();const index=this.values.findIndex(v=>v.ui_id===button.closest('.provider-card').dataset.providerId),kind=button.dataset.providerAction;if(kind==='remove'){this.keys.delete(this.values[index].ui_id);this.values.splice(index,1);this.render();return;}if(kind==='up'||kind==='down'){const next=index+(kind==='up'?-1:1);[this.values[index],this.values[next]]=[this.values[next],this.values[index]];this.render();return;}
    const row=this.values[index];
    if(kind==='choose'){if(!row.models.includes(button.dataset.providerModel)){if(row.models.length>=4)throw Error('最多选择 4 个模型');row.models.push(button.dataset.providerModel);button.closest('.provider-card').querySelector('[data-provider-field="models"]').value=row.models.join('\n');}return;}
    const primary=this.primary(),runtime=this.runtime([row],kind==='detect')[0];const status=button.closest('.provider-card').querySelector('[data-provider-status]');status.textContent=kind==='detect'?'正在检测…':'正在逐一测试模型…';button.disabled=true;
    try{const base={...Object.fromEntries(transportFields.map(k=>[k,runtime[k]])),api_key:row.inherit_primary_key?primary.api_key:runtime.api_key};
      if(kind==='detect'){const response=await this.api('models/discover',{method:'POST',json:base});const result=await response.json();status.textContent=result.message;if(result.models)button.closest('.provider-card').querySelector('[data-provider-models]').innerHTML=result.models.filter(m=>m.text_candidate).map(m=>`<button type="button" class="model-chip" data-provider-action="choose" data-provider-model="${e(m.id)}">＋ ${e(m.id)}</button>`).join('');}
      else{const results=[];for(const model of row.models){try{const response=await this.api('models/test',{method:'POST',json:{...base,layout_model:model,translation_model:model}});const result=await response.json();results.push(model+'：'+result.message);}catch(error){results.push(model+'：'+error.message);}status.textContent=results.join('；');}}
    }finally{button.disabled=false;}}
}
